"""Write unicode_tables.go: the characters that Python 3.13 (Unicode 15.1) reads as printable and as
whitespace.

The platform's checks ask str.isprintable(), str.split() and str.strip() of the text a declaration
holds, and Python answers by the Unicode version it ships. Go's unicode package ships a newer one,
so a character assigned after 15.1 is printable to Go and not to Python. This script reads Python's
own answers, one character at a time, and writes them as Go range tables, so the port refuses
what the platform refuses.

    python3 testdata/gen-unicode-tables.py --out unicode_tables.go

It refuses to run under a Python whose Unicode data is not 15.1.0, the version of Python 3.13.
"""

import argparse
import sys
import unicodedata
from pathlib import Path

UNICODE_VERSION = "15.1.0"
LATIN1_MAX = 0xFF


def ranges(test):
    """The inclusive runs of code points for which test(chr(code point)) holds."""
    runs, start = [], None
    for code in range(0x110000):
        if test(chr(code)):
            if start is None:
                start = code
        elif start is not None:
            runs.append((start, code - 1))
            start = None
    if start is not None:
        runs.append((start, 0x10FFFF))
    return runs


def table(name, comment, runs):
    """One unicode.RangeTable literal; a run that crosses 0xFFFF is split, as the type needs."""
    short, long = [], []
    for low, high in runs:
        if high <= 0xFFFF:
            short.append((low, high))
        elif low > 0xFFFF:
            long.append((low, high))
        else:
            short.append((low, 0xFFFF))
            long.append((0x10000, high))
    lines = [comment, f"var {name} = &unicode.RangeTable{{"]
    if short:
        lines.append("\tR16: []unicode.Range16{")
        lines.extend(f"\t\t{{Lo: {low:#06x}, Hi: {high:#06x}, Stride: 1}}," for low, high in short)
        lines.append("\t},")
    if long:
        lines.append("\tR32: []unicode.Range32{")
        lines.extend(f"\t\t{{Lo: {low:#08x}, Hi: {high:#08x}, Stride: 1}}," for low, high in long)
        lines.append("\t},")
    lines.append(f"\tLatinOffset: {sum(1 for _, high in short if high <= LATIN1_MAX)},")
    lines.append("}")
    return "\n".join(lines)


def main():
    parser = argparse.ArgumentParser(description=__doc__.split("\n")[0])
    parser.add_argument("--out", required=True, help="the Go file to write, such as unicode_tables.go")
    args = parser.parse_args()
    if unicodedata.unidata_version != UNICODE_VERSION:
        sys.exit(f"this Python holds Unicode {unicodedata.unidata_version}, and the tables are of {UNICODE_VERSION} "
                 "(Python 3.13): run it under a python3 of that version")
    python = ".".join(map(str, sys.version_info[:3]))
    text = "\n\n".join([
        f"// Code generated by testdata/gen-unicode-tables.py (Python {python}, Unicode "
        f"{unicodedata.unidata_version}); DO NOT EDIT.\n\npackage charts\n\nimport \"unicode\"",
        table("printableTable", "// printableTable holds the characters for which Python's str.isprintable() is true.",
              ranges(str.isprintable)),
        table("spaceTable", "// spaceTable holds the characters for which Python's str.isspace() is true, which are the "
              "ones\n// that str.split(), str.strip() and a regular expression's \\s and \\S read as white space.",
              ranges(str.isspace)),
    ])
    Path(args.out).write_text(text + "\n", encoding="utf-8")


if __name__ == "__main__":
    main()
